/*
 * DavinciUI typeset — prose styling for rendered markdown.
 *
 * One CSS file you own. Wrap rendered markdown in `.typeset` plus a
 * preset (`.typeset-docs`, `.typeset-chat`, `.typeset-compact`) and every
 * element inside inherits sizing, spacing, and theme automatically.
 *
 * Rhythm is controlled by three values. Everything else — heading sizes,
 * list indents, gaps around rules — derives from them:
 *
 *   --typeset-size    base text size (1em follows the container)
 *   --typeset-leading  line height
 *   --typeset-flow     space between blocks
 *
 * Colors, fonts, and radius come from your theme tokens, so dark mode
 * follows automatically. All element selectors use :where(), so plain
 * Tailwind utilities and CSS on an element win without !important.
 * Spacing flows one direction (margin-block-start only) with no
 * :last-child / :has() / :empty rules, so streaming a new block never
 * restyles the blocks above it.
 */

.typeset {
  --typeset-font-body: var(--font-sans);
  --typeset-font-heading: var(--font-heading);
  --typeset-font-mono: var(--font-mono);

  --typeset-size: 1em;
  --typeset-leading: 1.75;
  --typeset-flow: 1.25em;

  font-family: var(--typeset-font-body);
  font-size: var(--typeset-size);
  line-height: var(--typeset-leading);
  color: var(--foreground);
  overflow-wrap: break-word;
}

/* Tighter preset for chat and compact UI. */
.typeset-chat,
.typeset-compact {
  --typeset-leading: 1.6;
  --typeset-flow: 1em;
}

.typeset-compact {
  --typeset-size: 14px;
}

/* Roomier preset for docs and articles. */
.typeset-docs {
  --typeset-size: 15px;
  --typeset-flow: 1.5em;
}

/* Headings derive their scale from the base size. */
.typeset :where(h1, h2, h3, h4):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-family: var(--typeset-font-heading);
  font-weight: 600;
  letter-spacing: -0.02em;
  text-wrap: balance;
  scroll-margin-block: 5rem;
  margin-block-start: calc(var(--typeset-flow) * 1.5);
}

.typeset :where(h1):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-size: 2em;
  line-height: 1.15;
}

.typeset :where(h2):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-size: 1.5em;
  line-height: 1.25;
}

.typeset :where(h3):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-size: 1.25em;
  line-height: 1.35;
}

.typeset :where(h4):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-size: 1.125em;
  line-height: 1.45;
}

.typeset :where(p, ul, ol, blockquote, pre, table, hr, img, video, figure):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  margin-block-start: var(--typeset-flow);
}

.typeset :where(a):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  color: var(--primary);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
}

.typeset :where(strong):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-weight: 600;
}

.typeset :where(small):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-size: 0.875em;
}

.typeset :where(ul, ol):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  padding-inline-start: 1.5em;
}

.typeset :where(li):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  margin-block-start: 0.375em;
}

.typeset :where(li > ul, li > ol):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  margin-block-start: 0.375em;
}

.typeset :where(ul > li)::marker:not(:where(.not-typeset *, [data-not-typeset] *)) {
  color: var(--muted-foreground);
}

.typeset :where(blockquote):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-style: italic;
  color: var(--muted-foreground);
  border-inline-start: 2px solid var(--border);
  padding-inline-start: 1em;
}

.typeset :where(blockquote p):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  margin-block-start: 0.75em;
}

.typeset :where(code):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-family: var(--typeset-font-mono);
  font-size: 0.85em;
  background: var(--muted);
  border-radius: var(--radius-sm);
  padding: 0.15em 0.375em;
}

.typeset :where(pre):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  background: var(--muted);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1em;
  overflow-x: auto;
}

.typeset :where(pre code):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  background: transparent;
  border-radius: 0;
  padding: 0;
  font-size: 0.85em;
  line-height: 1.7;
}

.typeset :where(kbd):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-family: var(--typeset-font-mono);
  font-size: 0.8em;
  background: var(--muted);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.1em 0.375em;
}

.typeset :where(hr):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  border: none;
  border-block-start: 1px solid var(--border);
  margin-block-start: calc(var(--typeset-flow) * 1.5);
}

.typeset :where(table):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  width: 100%;
  font-size: 0.875em;
  line-height: 1.6;
  border-collapse: collapse;
}

.typeset :where(th):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  font-family: var(--typeset-font-heading);
  font-weight: 600;
  text-align: start;
  padding: 0.5em 0.75em;
  border-block-end: 1px solid var(--border);
}

.typeset :where(td):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  padding: 0.5em 0.75em;
  border-block-start: 1px solid var(--border);
  vertical-align: top;
}

.typeset :where(img, video):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
  max-width: 100%;
  height: auto;
  border-radius: var(--radius-lg);
}

/* Horizontal scroll for wide tables and blocks. */
.typeset-scroll {
  overflow-x: auto;
}
